const upsertMonitorInstance = `-- name: UpsertMonitorInstance :exec
INSERT INTO monitor_instances (workspace_id, service_id, instance, version, status, first_seen_at, last_seen_at)
SELECT $1, $2, $3, $4, $5, $6, $6
WHERE (SELECT count(*) FROM monitor_instances WHERE workspace_id = $1 AND service_id = $2) < 200
   OR EXISTS (SELECT 1 FROM monitor_instances WHERE workspace_id = $1 AND service_id = $2 AND instance = $3)
ON CONFLICT (service_id, instance) DO UPDATE SET version = coalesce(excluded.version, monitor_instances.version),
    status = coalesce(excluded.status, monitor_instances.status), last_seen_at = greatest(monitor_instances.last_seen_at, excluded.last_seen_at)
`

type UpsertMonitorInstanceParams struct {
	WorkspaceID uuid.UUID
	ServiceID   uuid.UUID
	Instance    string
	Version     *string
	Status      *string
	At          time.Time
}

// A new instance is taken while the service has fewer than 200.
func (q *Queries) UpsertMonitorInstance(ctx context.Context, arg UpsertMonitorInstanceParams) error {
	_, err := q.db.Exec(ctx, upsertMonitorInstance,
		arg.WorkspaceID,
		arg.ServiceID,
		arg.Instance,
		arg.Version,
		arg.Status,
		arg.At,
	)
	return err
}
